import { randomBytes } from "crypto";
import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { decrypt, encrypt } from "./crypto";

// Shared with tests/unit/test_credential_crypto.py; generated by Node crypto
// using the fixed 32-byte key and IV described there.
const FIXTURE_KEY_B64 = "CwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCwsLCws=";
const NODE_BLOB =
  "AAECAwQFBgcICQoL:p06uXPcouNmno+nMmO/COA==:iAHivVSyFlbamd1nGXMW8wfNuGkcoEhsq5j/Q2XQ";
const NODE_PLAINTEXT = "sk-test-fixture-not-a-real-key";

function withEncryptionKey(key: string, run: () => void): void {
  const previous = process.env.CREDENTIAL_ENCRYPTION_KEY;
  process.env.CREDENTIAL_ENCRYPTION_KEY = key;
  try {
    run();
  } finally {
    if (previous === undefined) delete process.env.CREDENTIAL_ENCRYPTION_KEY;
    else process.env.CREDENTIAL_ENCRYPTION_KEY = previous;
  }
}

describe("crypto (AES-256-GCM)", () => {
  const original = process.env.CREDENTIAL_ENCRYPTION_KEY;

  beforeAll(() => {
    // 32-byte key, base64 — a throwaway test key, never a real secret.
    process.env.CREDENTIAL_ENCRYPTION_KEY = randomBytes(32).toString("base64");
  });
  afterAll(() => {
    if (original === undefined) delete process.env.CREDENTIAL_ENCRYPTION_KEY;
    else process.env.CREDENTIAL_ENCRYPTION_KEY = original;
  });

  it("round-trips plaintext", () => {
    const plaintext = "sp-client-value-«ünïçøde»-123";
    const ct = encrypt(plaintext);
    expect(ct).not.toContain(plaintext);
    expect(decrypt(ct)).toBe(plaintext);
  });

  it("produces a unique IV per call (ciphertext differs for same input)", () => {
    const a = encrypt("same");
    const b = encrypt("same");
    expect(a).not.toBe(b);
    expect(decrypt(a)).toBe("same");
    expect(decrypt(b)).toBe("same");
  });

  it("uses the iv:tag:ciphertext base64 format", () => {
    const parts = encrypt("x").split(":");
    expect(parts).toHaveLength(3);
    parts.forEach((p) => expect(p).toMatch(/^[A-Za-z0-9+/]+=*$/));
  });

  it("decrypts the shared Node-generated Python interoperability vector", () => {
    withEncryptionKey(FIXTURE_KEY_B64, () => {
      expect(decrypt(NODE_BLOB)).toBe(NODE_PLAINTEXT);
    });
  });

  it("rejects malformed base64 in the encryption key instead of silently ignoring it", () => {
    const validKeyWithJunk = `${Buffer.alloc(32, 0x0b).toString("base64")}!`;
    withEncryptionKey(validKeyWithJunk, () => {
      expect(() => encrypt("not stored")).toThrow(
        "CREDENTIAL_ENCRYPTION_KEY must be valid base64",
      );
    });
  });

  it("rejects malformed base64 and non-standard IV or tag lengths", () => {
    const [iv, tag, data] = encrypt("strict encoding").split(":");
    expect(() => decrypt([`${iv}!`, tag, data].join(":"))).toThrow(
      "Invalid ciphertext encoding",
    );
    expect(() => decrypt([iv, `${tag}!`, data].join(":"))).toThrow(
      "Invalid ciphertext encoding",
    );
    expect(() => decrypt([iv, tag, `${data}!`].join(":"))).toThrow(
      "Invalid ciphertext encoding",
    );
    expect(() => decrypt(["AA==", tag, data].join(":"))).toThrow(
      "Invalid ciphertext format",
    );
    expect(() => decrypt([iv, Buffer.alloc(15).toString("base64"), data].join(":"))).toThrow(
      "Invalid ciphertext format",
    );
  });

  it("rejects a tampered ciphertext (GCM auth tag mismatch)", () => {
    const ct = encrypt("tamper-me");
    const [iv, tag, data] = ct.split(":");
    // Flip a byte in the ciphertext segment.
    const buf = Buffer.from(data, "base64");
    buf[0] = buf[0] ^ 0xff;
    const tampered = [iv, tag, buf.toString("base64")].join(":");
    expect(() => decrypt(tampered)).toThrow();
  });

  it("rejects a tampered auth tag", () => {
    const ct = encrypt("tamper-tag");
    const [iv, tag, data] = ct.split(":");
    const buf = Buffer.from(tag, "base64");
    buf[0] = buf[0] ^ 0xff;
    expect(() => decrypt([iv, buf.toString("base64"), data].join(":"))).toThrow();
  });

  it("rejects a malformed ciphertext string", () => {
    expect(() => decrypt("not-a-valid-format")).toThrow("Invalid ciphertext format");
  });
});
